function getScoreEmoji(score) {
  if (score >= 80) return '🟢';
  if (score >= 60) return '🟡';
  if (score >= 40) return '🟠';
  return '🔴';
}

function getScoreStatus(score) {
  if (score >= 90) return 'EXCELLENT';
  if (score >= 75) return 'BON';
  if (score >= 50) return 'MOYEN';
  if (score >= 25) return 'FAIBLE';
  return 'CRITIQUE';
}

