function cleanForSupabase(htmlContent) {
  if (!htmlContent || typeof htmlContent !== 'string') return '';
  let cleaned = htmlContent.replace(/[\x00-\x1F\x7F]/g, '');
  if (cleaned.length > 100000) {
    cleaned = cleaned.substring(0, 100000) + '...</body></html>';
  }
  return cleaned;
}

