function generatePlanActionHTML(plan) {
  if (!plan || plan.length === 0) {
    return `<div class="bg-green-100 border-l-4 border-green-500 text-green-700 p-4 rounded-r-lg h-full flex flex-col justify-center" role="alert">
              <p class="font-bold">Excellent travail !</p><p>Aucun point d'amélioration majeur n'a été détecté.</p>
            </div>`;
  }
  return plan.map(item => {
    let icon = '💡'; let priorityColorClass = 'bg-gray-400'; let urgencyText = 'Faible';
    if (item.category === 'Modernité') icon = '🎨'; if (item.category === 'SEO') icon = '🎯';
    if (item.category === 'Sécurité') icon = '🛡️'; if (item.category === 'Performance') icon = '⚡';

    // Gestion de la priorité et de l'urgence
    if (item.priority === 1) { priorityColorClass = 'bg-red-600'; urgencyText = 'Élevée'; }
    else if (item.priority === 2) { priorityColorClass = 'bg-orange-500'; urgencyText = 'Moyenne'; }
    else if (item.priority === 3) { priorityColorClass = 'bg-blue-500'; urgencyText = 'Faible'; }

    // Si urgency est défini dans l'objet, l'utiliser
    if (item.urgency) urgencyText = item.urgency;

    return `<div class="bg-white border border-gray-200 rounded-lg p-3 mb-2 shadow-sm">
              <div class="flex items-center mb-2"><span class="text-lg mr-2">${icon}</span><h5 class="font-bold text-gray-500 uppercase text-xs tracking-wider">${item.category}</h5></div>
              <p class="text-sm font-semibold text-gray-800 mb-2">${item.text}</p>
              <p class="text-xs text-green-700 mb-2"><strong>Impact :</strong> ${item.impact}</p>
              <div class="text-right"><span class="inline-block rounded-full px-2 py-1 text-xs font-bold text-white ${priorityColorClass}">Urgence : ${urgencyText}</span></div>
            </div>`;
  }).join('');
}

function generateImpactsHTML(impacts) {
  return impacts.map(i => `<div class="theme-bg-light rounded-xl p-3 text-center shadow-md">
      <div class="text-3xl mb-2">${i.icon}</div><h4 class="font-bold text-sm text-gray-800">${i.title}</h4>
      <p class="text-gray-600 text-xs mt-1">${i.description}</p></div>`).join('');
}

function generateMethodHTML(method) {
  return method.map(m => `<div class="theme-bg-light rounded-xl p-4 flex items-center space-x-3">
        <div class="bg-white p-2 rounded-full text-2xl">${m.icon}</div>
        <div>
