// VALIDATION DES DONNÉES DE SUPABASE
const record = $json;
const context = $('🧩 Parse Context').item.json;

// Vérifier que les champs requis existent
if (!record.url) {
  throw new Error('Champ URL manquant dans Supabase');
}

// Utiliser email_client au lieu de email
let email = record.email_client;
// Après la ligne email = record.email_client;
console.log('Email récupéré depuis Supabase:', email);
