if (!email) {
  email = `audit-${record.id}@auto-generated.com`;
  console.log(`Email généré automatiquement: ${email}`);
}

// Nettoyage URL
let cleanUrl = String(record.url).trim();
if (!cleanUrl.startsWith('http')) {
  cleanUrl = 'https://' + cleanUrl;
}

// Extraction du domaine
const domainMatch = cleanUrl.match(/^(?:https?:\/\/)?(?:[^@\n]+@)?(?:www\.)?([^:\/\n?]+)/im);
const domain = domainMatch ? domainMatch[1] : null;

if (!domain) {
  throw new Error(`Impossible d'extraire le domaine de l'URL: ${cleanUrl}`);
}

// Merge contexte + données record
const enrichedContext = {
  ...context,
  url: cleanUrl,
  domain: domain,
  email: email, // Maintenant ça vient de email_client
  originalRecord: record
};

return { json: enrichedContext };

// PARSING ULTRA-ROBUSTE DU CONTEXTE
const redisValue = $json.data;

if (redisValue === null || redisValue === undefined) {
  console.log('[WORKER] File vide, pas de traitement.');
  return null;
}

let context;
if (typeof redisValue === 'string') {
  try {
    context = JSON.parse(redisValue);
  } catch (e) {
    throw new Error('Contexte JSON invalide: ' + e.message);
  }
} else if (typeof redisValue === 'object') {
  context = redisValue;
} else {
  throw new Error('Donnée invalide depuis Redis: format inattendu.');
}

// CORRECTION : Gérer les différents noms de champs
if (!context.recordId && context.id) {
  context.recordId = context.id;
}

// NOUVEAU : Nettoyer l'UUID des guillemets/échappements supplémentaires
if (context.recordId) {
  let cleanId = String(context.recordId);
  cleanId = cleanId.replace(/^["']|["']$/g, '');
  cleanId = cleanId.replace(/\\"/g, '"');

  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(cleanId)) {
    throw new Error(`Format UUID invalide: ${cleanId}`);
  }

  context.recordId = cleanId;
}

const required = ['recordId', 'delivery_method'];
for (const field of required) {
  if (!context[field]) {
    throw new Error(`Champ requis manquant dans le contexte: ${field}`);
  }
}

console.log(`[WORKER] Traitement pour recordId: ${context.recordId}`);
return { json: context };
